  // Also get any filter elements
  const filterElements = Array.from(document.querySelectorAll('[class*="filter"], [class*="Filter"]')).map(el => el.textContent.trim().slice(0, 100));

  return {
    title: document.title,
    captchaVisible,
    trainCardCount: trainCards.length,
    bodyTextSnippet: document.body.innerText.slice(0, 3000),
    filterSnippets: filterElements.slice(0, 10)
  };
});

