    className: el.className,
    parentTag: el.parentElement?.tagName,
    parentClass: el.parentElement?.className,
    rect: el.getBoundingClientRect()
  }));

  // Find all buttons that say "Select"
  const selectButtons = Array.from(document.querySelectorAll('button, div, span')).filter(el => 
    el.innerText && el.innerText.trim() === 'Select'
  ).map(el => ({
    tagName: el.tagName,
    className: el.className,
    rect: el.getBoundingClientRect(),
    parentText: el.parentElement?.parentElement?.innerText?.replace(/\n+/g, ' | ')
  }));

  return { captchaRect, highSpeedElements, selectCount: selectButtons.length, firstFewSelects: selectButtons.slice(0, 3) };
});

